astpost-date"><i class="fa fa-calendar" aria-hidden="true"></i>&nbsp;<?php the_time('d M Y'); ?><br><i class="fa fa-eye-slash" aria-hidden="true"></i>&nbsp;<?php setPostViews(get_the_ID()); ?><?php echo getPostViews(get_the_ID()); ?></div><div class="yglastpost-title"><h4><?php the_title(); ?></h4></div></div></div><?php endwhile; ?><?php wp_reset_query(); ?><div class="clear"></div></div></div></div><?php get_footer(); ?>